"use strict";var CSAT_LABELS={1:"Muy insatisfecho",2:"Insatisfecho",3:"Neutral",4:"Satisfecho",5:"Muy satisfecho"};function csatStars(n){for(var s="",t=1;t<=5;t++)s+='<i class="fa-solid fa-star tkt-csat-star'+(t<=n?" on":"")+'"></i>';return s}function openCsatModal(n){var s=openModal(modalShell({icon:"fa-regular fa-face-smile",kicker:"Ticket \xB7 satisfacci\xF3n",titleChip:n.ticket_number,title:"Encuesta CSAT",width:"sm",body:'<div class="tkt-empty-box">Cargando\u2026</div>',foot:'<button type="button" class="tkt-btn" data-modal-close>Cerrar</button>'}));$.getJSON(n.url_csat).done(function(t){var a=t&&t.csat;if(!a){s.find(".tkt-modal-body").html('<div class="tkt-empty-box">No se pudo cargar la valoraci\xF3n.</div>');return}var e;a.rating?e='<div class="tkt-cap">Respuesta del cliente</div><div class="tkt-csat-head"><span class="tkt-csat-score">'+a.rating+'</span><span class="tkt-csat-main"><span class="tkt-csat-stars">'+csatStars(a.rating)+'</span><span class="tkt-csat-label">'+escapeHtml(CSAT_LABELS[a.rating]||"")+(a.rated_at_human?" \xB7 respondida el "+escapeHtml(a.rated_at_human):"")+"</span></span></div>"+(a.comment?'<blockquote class="tkt-form-quote">'+escapeHtml(a.comment)+"</blockquote>":"")+(a.reason?'<div class="tkt-kv"><span class="k">Motivo</span><span class="v">'+escapeHtml(a.reason)+"</span></div>":""):e='<div class="tkt-empty-box">Este ticket todav\xEDa no tiene valoraci\xF3n.</div>'+(a.can_resend?'<button type="button" class="tkt-btn tkt-w-100" id="tkt-csat-resend">Reenviar encuesta de satisfacci\xF3n</button>':""),e+='<div class="tkt-kv-grid tkt-csat-meta"><span>agente</span><span>'+escapeHtml(a.agent||"\u2014")+"</span><span>tiempo de resoluci\xF3n</span><span>"+escapeHtml(a.resolution_human||"\u2014")+"</span><span>reaperturas</span><span>"+a.reopenings+"</span><span>media del agente</span><span>"+(a.agent_average!==null?a.agent_average+" / 5":"sin valoraciones")+"</span></div>",s.find(".tkt-modal-body").html(e)}).fail(function(){s.find(".tkt-modal-body").html('<div class="tkt-empty-box">No se pudo cargar la valoraci\xF3n.</div>')}),s.on("click","#tkt-csat-resend",function(){var t=$(this).prop("disabled",!0).text("Enviando\u2026");$.ajax({url:n.url_send_csat,method:"POST",headers:{Accept:"application/json"}}).done(function(a){window.toastr&&toastr.success(a&&a.message||"Encuesta reenviada."),closeModal()}).fail(function(a){var e=apiErrorMessage(a,"No se pudo reenviar la encuesta.");tktNotify("error",e),t.prop("disabled",!1).text("Reenviar encuesta de satisfacci\xF3n")})})}
